-- ── 2) crossleague approvals in model_registry (REAL governance, UCL+UEL only) ──
-- Evidence: lab/champions_crossleague_v1/validation_v2.json per-competition OOS.
--   UCL n=207 dBrier +0.0166 ECE 0.018 · UEL n=136 dBrier +0.0285 ECE 0.028.
-- Conference/Concacaf/CWC/AFC/Libertadores showed NO OOS benefit or insufficient
-- sample -> NOT inserted (stay fail-close). Sudamericana = business veto.
insert into v2.model_registry (sport,model_name,model_version,liga_id,liga_nombre,approved,notes)
select * from (values
 ('soccer','crossleague','crossleague_v1',2,'UEFA Champions League',true,
  'BLOQUE1 OOS: dBrier +0.0166 ECE 0.018 n=207 (validation_v2.json); domestic floor=15'),
 ('soccer','crossleague','crossleague_v1',3,'UEFA Europa League',true,
  'BLOQUE1 OOS: dBrier +0.0285 ECE 0.028 n=136 (validation_v2.json); domestic floor=15')
) v(sport,model_name,model_version,liga_id,liga_nombre,approved,notes)
where not exists (
  select 1 from v2.model_registry r
  where r.sport=v.sport and r.model_name=v.model_name and r.model_version=v.model_version and r.liga_id=v.liga_id);

-- ── 3) SEAL the phi snapshot at its DOCUMENTED training cutoff ───────────────
-- Provenance: lab/champions_crossleague_v1/validation_v2.json -> leakage.max_fecha =
-- 2026-09-08 (the latest cross-league kickoff used to identify phi). The sealed cutoff
-- is therefore 2026-09-09 00:00:00+00 (data used: kickoff < cutoff). That is strictly
-- BEFORE the 2026-09-10 12:00Z decision epoch => no phi leakage into the owner fixtures.
-- iss037 contract: the builder must read phi via fn_crossleague_phi_asof (sealed), never
-- the live mutable v2.liga_fuerza.
select v2.fn_seal_liga_fuerza_snapshot('crossleague_v1', timestamptz '2026-09-09 00:00:00+00', 10.0, 39);

